// Original fresh in-memory LEDGERS -> HEADS ledger/outside-staff raw seed search.
// Original Scanner owns pitch references, selection and offsets. No native outputs.
import org.audiveris.omr.sheet.Book;
import java.util.*;import java.nio.file.*;import java.awt.geom.*;import java.security.*;
public class HeadLedgerSearchProbe extends HeadSeedSearchProbe {
 public HeadLedgerSearchProbe(Book b,SortedSet<Integer> ids){super(b,ids);}
 String line(Object a)throws Exception{Point2D l=(Point2D)get(a,"left"),r=(Point2D)get(a,"right");return "["+l.getX()+","+l.getY()+","+r.getX()+","+r.getY()+"]";}
 String observe(Object b,Object adapter,Object staff,Object table,Object catalog,List<?> seeds,int[]xo,int index,int order,int dir,int pitch)throws Exception{
  Object scanner=make("sheet.note.NoteHeadsBuilder$Scanner",b,adapter,null,dir,pitch,true);int[]yo=(int[])get(scanner,"yOffsets");List<?>selected=(List<?>)call(b,"getGlyphsSlice",seeds,get(scanner,"seedsArea"));List<String>records=new ArrayList<>(),further=new ArrayList<>(),ys=new ArrayList<>();TreeSet<Integer>xs=new TreeSet<>();Point2D l=(Point2D)get(adapter,"left"),z=(Point2D)get(adapter,"right");xs.add((int)Math.ceil(l.getX())-1);xs.add((int)Math.ceil(l.getX()));xs.add((int)Math.floor(z.getX()));xs.add((int)Math.floor(z.getX())+1);xs.add((int)Math.rint((l.getX()+z.getX())/2));
  for(Object a:(List<?>)get(scanner,"ledgers")){further.add(line(a));Point2D p=(Point2D)get(a,"left"),q=(Point2D)get(a,"right");for(int x:new int[]{(int)Math.ceil(p.getX())-1,(int)Math.ceil(p.getX()),(int)Math.floor(q.getX()),(int)Math.floor(q.getX())+1})xs.add(x);}
  for(int x:xs)ys.add("{\"x\":"+x+",\"y\":"+call(scanner,"getTheoreticalOrdinate",x)+"}");
  for(Object seed:selected){Point2D center=(Point2D)call(seed,"getCenter2D"),a=(Point2D)call(seed,"getStartPoint",vertical),c=(Point2D)call(seed,"getStopPoint",vertical);int rough=(int)Math.rint(center.getX());double yl=(Double)call(adapter,"yAt",(double)rough);int x0=(int)Math.rint(a.getX()+(c.getX()-a.getX())*(yl-a.getY())/(c.getY()-a.getY()));int y0=(Integer)call(scanner,"getTheoreticalOrdinate",x0);List<String>ms=new ArrayList<>();for(String an:new String[]{"LEFT_STEM","RIGHT_STEM"})for(String sh:new String[]{"NOTEHEAD_BLACK","NOTEHEAD_VOID"}){String m=match(table,catalog,x0,y0,xo,yo,an,sh);if(!m.equals("null"))ms.add(m);}records.add("{\"seed\":"+glyph(seed)+",\"x0\":"+x0+",\"y0\":"+y0+",\"matches\":["+String.join(",",ms)+"]}");}
  return "{\"ledger_index\":"+index+",\"ledger_order\":"+order+",\"dir\":"+dir+",\"pitch\":"+pitch+",\"main_line\":"+line(adapter)+",\"further_lines\":["+String.join(",",further)+"],\"x_offsets\":"+Arrays.toString(xo)+",\"y_offsets\":"+Arrays.toString(yo)+",\"ordinate_controls\":["+String.join(",",ys)+"],\"seeds\":["+String.join(",",records)+"]}";
 }
 public void process(){try{
  sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");for(String step:new String[]{"sheet.grid.GridStep","sheet.header.HeadersStep","sheet.stem.StemSeedsStep","sheet.beam.BeamsStep","sheet.ledger.LedgersStep"})call(make(step),"doit",sheet);horizontal=Class.forName("org.audiveris.omr.run.Orientation").getField("HORIZONTAL").get(null);vertical=Class.forName("org.audiveris.omr.run.Orientation").getField("VERTICAL").get(null);Object table=call(make("sheet.note.DistancesBuilder",sheet),"buildDistances");int w=(Integer)call(table,"getWidth"),h=(Integer)call(table,"getHeight");MessageDigest d=MessageDigest.getInstance("SHA-256"),m=MessageDigest.getInstance("SHA-256");for(int i=0;i<w*h;i++){int v=(Integer)call(table,"getValue",i);d.update((byte)(v>>>8));d.update((byte)v);m.update(v==-1?(byte)0:(byte)255);}String distance=HexFormat.of().formatHex(d.digest()),mask=HexFormat.of().formatHex(m.digest());Object family=Class.forName("org.audiveris.omr.ui.symbol.MusicFamily").getField("Bravura").get(null),factory=staticCall("image.TemplateFactory","getInstance"),group=Class.forName("org.audiveris.omr.glyph.GlyphGroup").getField("VERTICAL_SEED").get(null);List<String>systems=new ArrayList<>();
  for(Object sys:(List<?>)call(sheet,"getSystems")){List<?>seeds=(List<?>)call(sys,"getGroupedGlyphs",group);List<String>staffs=new ArrayList<>();Object b=make("sheet.note.NoteHeadsBuilder",sys,table,new ArrayList<>(),make("sheet.note.HeadSeedTally"),Boolean.FALSE,new TreeMap<>());setField(b,"systemBarAreas",new ArrayList<>());setField(b,"systemCompetitors",new ArrayList<>());int[]xo=(int[])get(b,"xOffsets");
   for(Object staff:(List<?>)call(sys,"getStaves")){Object catalog=call(factory,"getCatalog",family,call(staff,"getHeadPointSize"));setField(b,"catalog",catalog);Object part=call(staff,"getPart");boolean merged=(Boolean)call(part,"isMerged"),mf=merged&&call(part,"getFirstStaff")==staff,ml=merged&&call(part,"getLastStaff")==staff;List<String>scans=new ArrayList<>(),inputs=new ArrayList<>(),seedInputs=new ArrayList<>();for(Object seed:seeds)seedInputs.add(glyph(seed));
    for(var entry:((Map<?,?>)call(staff,"getLedgerMap")).entrySet()){int index=(Integer)entry.getKey();for(Object ledger:(List<?>)entry.getValue()){Object adapter=make("sheet.note.NoteHeadsBuilder$LedgerAdapter",b,staff,"",call(ledger,"getGlyph"));inputs.add("{\"index\":"+index+",\"line\":"+line(adapter)+"}");}}
    for(int sign:new int[]{-1,1}){boolean lookFurther=!(sign>0&&mf||sign<0&&ml);for(int index=sign;;index+=sign){List<?>ls=(List<?>)call(staff,"getLedgers",index);if(ls==null||ls.isEmpty())break;int pitch=sign*(4+2*Math.abs(index));for(int n=0;n<ls.size();n++){Object adapter=make("sheet.note.NoteHeadsBuilder$LedgerAdapter",b,staff,"",call(ls.get(n),"getGlyph"));scans.add(observe(b,adapter,staff,table,catalog,seeds,xo,index,n,0,pitch));if(lookFurther)scans.add(observe(b,adapter,staff,table,catalog,seeds,xo,index,n,sign,pitch+sign));}}}
    staffs.add("{\"staff_id\":"+call(staff,"getId")+",\"interline\":"+call(staff,"getSpecificInterline")+",\"merged_first\":"+mf+",\"merged_last\":"+ml+",\"ledger_lines\":["+String.join(",",inputs)+"],\"all_seeds\":["+String.join(",",seedInputs)+"],\"ledger_scanners\":["+String.join(",",scans)+"]}");}
   systems.add("{\"system_id\":"+call(sys,"getId")+",\"staffs\":["+String.join(",",staffs)+"]}");}
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"width\":"+w+",\"height\":"+h+",\"mask_sha256\":\""+mask+"\",\"distance_sha256_be_i16\":\""+distance+"\",\"systems\":["+String.join(",",systems)+"],\"scope\":\"Unmodified fresh original GRID through LEDGERS, DistancesBuilder, LedgerAdapter and Scanner reference/selection/offsets; raw black/void seed-template proposals before competitor/bar veto and registration. Signed contiguous ledger levels, merged-part limits and direct theoretical-ordinate controls.\"}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
